-- #1732/#1733 - staff-controlled checkout recovery. `CheckoutRecovery` (one per abandoned order, with
-- a lifecycle independent of the order's status) and its append-only `CheckoutRecoveryEvent` log
-- replace #1554's one-shot `AbandonedCheckoutReminder`. `DiscountKind.FREE_DELIVERY` and
-- `DiscountCode.restrictedToUserId` support single-use, customer-locked recovery incentives.
--
-- HAND-AUTHORED, not generated by `prisma migrate dev --create-only`: that command refuses on the
-- dev database and offers only `migrate reset`, which would delete every row - the open `#895`. The
-- DDL below is Prisma's own output from `prisma migrate diff --from-schema-datamodel <staging
-- schema> --to-schema-datamodel prisma/schema.prisma --script`, REORDERED so the old reminder rows
-- are copied into the new tables before `AbandonedCheckoutReminder` is removed (its foreign keys go
-- with the table). That is the only removal here, and it is intentional (spec R3).

-- CreateEnum
CREATE TYPE "CheckoutRecoveryStatus" AS ENUM ('PENDING', 'REVIEWED', 'EMAIL_SENT', 'RECOVERED', 'EXPIRED', 'SUPPRESSED');

-- CreateEnum
CREATE TYPE "CheckoutRecoveryEventKind" AS ENUM ('REVIEWED', 'INCENTIVE_ALLOCATED', 'INCENTIVE_REMOVED', 'EMAIL_SENT', 'EMAIL_RESENT', 'RESTORED', 'RECOVERED', 'SUPPRESSED', 'UNSUPPRESSED');

-- AlterEnum
ALTER TYPE "DiscountKind" ADD VALUE 'FREE_DELIVERY';

-- AlterTable
ALTER TABLE "DiscountCode" ADD COLUMN     "restrictedToUserId" TEXT;

-- CreateTable
CREATE TABLE "CheckoutRecovery" (
    "id" TEXT NOT NULL,
    "vendorId" TEXT NOT NULL,
    "orderId" TEXT NOT NULL,
    "status" "CheckoutRecoveryStatus" NOT NULL DEFAULT 'PENDING',
    "emailCount" INTEGER NOT NULL DEFAULT 0,
    "lastEmailedAt" TIMESTAMP(3),
    "discountCodeId" TEXT,
    "tokenHash" TEXT,
    "tokenExpiresAt" TIMESTAMP(3),
    "restoredAt" TIMESTAMP(3),
    "recoveredOrderId" TEXT,
    "recoveredAt" TIMESTAMP(3),
    "suppressReason" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

CONSTRAINT "CheckoutRecovery_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "CheckoutRecoveryEvent" (
    "id" TEXT NOT NULL,
    "recoveryId" TEXT NOT NULL,
    "vendorId" TEXT NOT NULL,
    "kind" "CheckoutRecoveryEventKind" NOT NULL,
    "actorUserId" TEXT,
    "discountCode" TEXT,
    "note" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

CONSTRAINT "CheckoutRecoveryEvent_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "CheckoutRecovery_orderId_key" ON "CheckoutRecovery"("orderId");

-- CreateIndex
CREATE UNIQUE INDEX "CheckoutRecovery_discountCodeId_key" ON "CheckoutRecovery"("discountCodeId");

-- CreateIndex
CREATE UNIQUE INDEX "CheckoutRecovery_tokenHash_key" ON "CheckoutRecovery"("tokenHash");

-- CreateIndex
CREATE UNIQUE INDEX "CheckoutRecovery_recoveredOrderId_key" ON "CheckoutRecovery"("recoveredOrderId");

-- CreateIndex
CREATE INDEX "CheckoutRecovery_vendorId_status_idx" ON "CheckoutRecovery"("vendorId", "status");

-- CreateIndex
CREATE INDEX "CheckoutRecoveryEvent_recoveryId_createdAt_idx" ON "CheckoutRecoveryEvent"("recoveryId", "createdAt");

-- AddForeignKey
ALTER TABLE "DiscountCode" ADD CONSTRAINT "DiscountCode_restrictedToUserId_fkey" FOREIGN KEY ("restrictedToUserId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "CheckoutRecovery" ADD CONSTRAINT "CheckoutRecovery_vendorId_fkey" FOREIGN KEY ("vendorId") REFERENCES "Vendor"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "CheckoutRecovery" ADD CONSTRAINT "CheckoutRecovery_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "CheckoutRecovery" ADD CONSTRAINT "CheckoutRecovery_discountCodeId_fkey" FOREIGN KEY ("discountCodeId") REFERENCES "DiscountCode"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "CheckoutRecovery" ADD CONSTRAINT "CheckoutRecovery_recoveredOrderId_fkey" FOREIGN KEY ("recoveredOrderId") REFERENCES "Order"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "CheckoutRecoveryEvent" ADD CONSTRAINT "CheckoutRecoveryEvent_recoveryId_fkey" FOREIGN KEY ("recoveryId") REFERENCES "CheckoutRecovery"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "CheckoutRecoveryEvent" ADD CONSTRAINT "CheckoutRecoveryEvent_vendorId_fkey" FOREIGN KEY ("vendorId") REFERENCES "Vendor"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "CheckoutRecoveryEvent" ADD CONSTRAINT "CheckoutRecoveryEvent_actorUserId_fkey" FOREIGN KEY ("actorUserId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- Carry every #1554 reminder over: the recovery keeps the reminder's id, and the send becomes its
-- first EMAIL_SENT event with the same actor, code text and time.
INSERT INTO "CheckoutRecovery" ("id", "vendorId", "orderId", "status", "emailCount", "lastEmailedAt", "createdAt", "updatedAt")
SELECT "id", "vendorId", "orderId", 'EMAIL_SENT', 1, "sentAt", "sentAt", "sentAt"
FROM "AbandonedCheckoutReminder";

INSERT INTO "CheckoutRecoveryEvent" ("id", "recoveryId", "vendorId", "kind", "actorUserId", "discountCode", "createdAt")
SELECT gen_random_uuid()::text, "id", "vendorId", 'EMAIL_SENT', "sentByUserId", "discountCode", "sentAt"
FROM "AbandonedCheckoutReminder";

-- DropTable
DROP TABLE "AbandonedCheckoutReminder";
